package org.eclipse.rdf4j.sail.nativerdf;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;

import java.nio.file.Path;

import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.sail.nativerdf.model.NativeValue;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class NativeAbsentBlankNodeReferenceTest {

	@Test
	void preparingAndEvaluatingAbsentReferencesDoesNotWriteIdentities(@TempDir Path directory) throws Exception {
		var repository = new SailRepository(new NativeStore(directory.toFile()));
		repository.init();
		try {
			try (var connection = repository.getConnection()) {
				var vf = SimpleValueFactory.getInstance();
				var absent = vf.createBNode("absent-reference");
				connection.add(vf.createIRI("urn:s"), vf.createIRI("urn:p"), vf.createLiteral("existing"));
				var dictionary = (ValueStore) repository.getValueFactory();
				assertEquals(NativeValue.UNKNOWN_ID, dictionary.getID(absent));
				var values = connection
						.prepareTupleQuery("SELECT ?node WHERE { VALUES ?node { <_:absent-reference> } }");
				assertEquals(NativeValue.UNKNOWN_ID, dictionary.getID(absent));
				try (var rows = values.evaluate()) {
					assertEquals(absent, rows.next().getValue("node"));
					assertFalse(rows.hasNext());
				}
				assertEquals(NativeValue.UNKNOWN_ID, dictionary.getID(absent));
				var expression = connection.prepareTupleQuery("SELECT (<_:absent-reference> AS ?node) WHERE {}");
				assertEquals(NativeValue.UNKNOWN_ID, dictionary.getID(absent));
				try (var rows = expression.evaluate()) {
					assertEquals(absent, rows.next().getValue("node"));
					assertFalse(rows.hasNext());
				}
				assertEquals(NativeValue.UNKNOWN_ID, dictionary.getID(absent));
				var ask = connection.prepareBooleanQuery("ASK { <_:absent-reference> ?p ?o }");
				assertEquals(NativeValue.UNKNOWN_ID, dictionary.getID(absent));
				assertFalse(ask.evaluate());
				assertEquals(NativeValue.UNKNOWN_ID, dictionary.getID(absent));
				assertEquals(1, connection.size());
				try (var statements = connection.getStatements(null, null, null, false)) {
					var statement = statements.next();
					assertEquals(vf.createIRI("urn:s"), statement.getSubject());
					assertEquals(vf.createIRI("urn:p"), statement.getPredicate());
					assertEquals(vf.createLiteral("existing"), statement.getObject());
					assertFalse(statements.hasNext());
				}
			}
		} finally {
			repository.shutDown();
		}
		var reopened = new SailRepository(new NativeStore(directory.toFile()));
		reopened.init();
		try {
			var absent = SimpleValueFactory.getInstance().createBNode("absent-reference");
			assertEquals(NativeValue.UNKNOWN_ID, ((ValueStore) reopened.getValueFactory()).getID(absent));
			try (var connection = reopened.getConnection()) {
				assertEquals(1, connection.size());
			}
		} finally {
			reopened.shutDown();
		}
	}
}
